def _decode():
    starts, classes = [], []
    n = shift = pos = 0
    for ch in _T:
        d = _A.index(ch)
        n |= (d & 31) << shift
        shift += 5
        if d < 32:
            pos += n >> 2
            starts.append(pos)
            classes.append(n & 3)
            n = shift = 0
    return starts, classes


_STARTS, _CLASSES = _decode()


def klass(cp):
    """0, 1 or 2 (print's width) or 3 (escaped), by bisection over the ranges."""
    lo, hi = 0, len(_STARTS) - 1
    if cp < _STARTS[0]:
        return 3
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if _STARTS[mid] <= cp:
            lo = mid
        else:
            hi = mid - 1
    return _CLASSES[lo]
